-- Phase C5.2: commercial physical fuel-and-oil stocktake.
-- Additive and idempotent; no legacy inventory table is altered.

ALTER TABLE "StationOperationalSettings"
    ADD COLUMN IF NOT EXISTS "StocktakeVarianceAlertPercent" numeric(5,2);

CREATE TABLE IF NOT EXISTS "StationStocktakes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StationId" integer NOT NULL REFERENCES "Stations" ("Id") ON DELETE RESTRICT,
    "SubStationId" integer NOT NULL REFERENCES "SubStations" ("Id") ON DELETE RESTRICT,
    "StocktakeDate" date NOT NULL,
    "Status" integer NOT NULL,
    "SubmittedByUserId" integer NOT NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    "SubmittedAt" timestamp with time zone NOT NULL,
    "ReviewedByUserId" integer NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    "ReviewedAt" timestamp with time zone NULL,
    "RejectionReason" varchar(1000) NULL,
    "Notes" varchar(2000) NULL,
    "ClientRequestId" uuid NOT NULL,
    "ConcurrencyToken" uuid NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL,
    "DeletedAt" timestamp with time zone NULL
);

CREATE TABLE IF NOT EXISTS "StationStocktakeFuelLines" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StocktakeId" integer NOT NULL REFERENCES "StationStocktakes" ("Id") ON DELETE CASCADE,
    "FuelTankId" integer NOT NULL REFERENCES "FuelTanks" ("Id") ON DELETE RESTRICT,
    "CountedLiters" numeric(18,3) NOT NULL,
    "BookLiters" numeric(18,3) NOT NULL,
    "DeadStockLiters" numeric(18,3) NOT NULL,
    "UsableCountedLiters" numeric(18,3) NOT NULL,
    "VarianceLiters" numeric(18,3) NOT NULL,
    "DipLevelCm" numeric(18,3) NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL,
    "DeletedAt" timestamp with time zone NULL
);

CREATE TABLE IF NOT EXISTS "StationStocktakeOilLines" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StocktakeId" integer NOT NULL REFERENCES "StationStocktakes" ("Id") ON DELETE CASCADE,
    "OilId" integer NOT NULL REFERENCES "Oils" ("Id") ON DELETE RESTRICT,
    "OilLookupId" integer NOT NULL REFERENCES "Lookups" ("Id") ON DELETE RESTRICT,
    "CountedLiters" numeric(18,3) NOT NULL,
    "BookLiters" numeric(18,3) NOT NULL,
    "VarianceLiters" numeric(18,3) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL,
    "DeletedAt" timestamp with time zone NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StationStocktakes_Station_Date_Request"
    ON "StationStocktakes" ("StationId", "StocktakeDate", "ClientRequestId")
    WHERE "DeletedAt" IS NULL;
CREATE INDEX IF NOT EXISTS "IX_StationStocktakes_Status_Date"
    ON "StationStocktakes" ("Status", "StocktakeDate") WHERE "DeletedAt" IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StationStocktakeFuelLines_Stocktake_Tank"
    ON "StationStocktakeFuelLines" ("StocktakeId", "FuelTankId") WHERE "DeletedAt" IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StationStocktakeOilLines_Stocktake_Oil"
    ON "StationStocktakeOilLines" ("StocktakeId", "OilId") WHERE "DeletedAt" IS NULL;
